def gain(ci,obj,policy='P3'):return record(REF[ci],policy,obj)['objective_value']-record(REF[ci],'P0',obj)['objective_value']
def peak(ci,obj):
    r=record(REF[ci],'P3',obj);s,h,b,e=r['peak_load_index'];p=C[ci]['products'][s];seats={'G':['business','first','second'],'D':['first','second','--'],'K':['hard seat','hard sleeper','soft sleeper']};return p['id']+' '+seats[p['tier']][b]

